import React, { useState, useMemo, useEffect } from 'react';
import { AnalysisState } from '../types';
import { useTranslation } from '../context/LanguageContext';
import { useExportData } from './Export/useExportData';
import ExportSidebar, { ExportTab } from './Export/ExportSidebar';
import ReportShell from './Export/ReportShell';
import OverallReport from './Export/OverallReport';
import PersonalReport from './Export/PersonalReport';
import TableReport from './Export/TableReport';

interface ExportViewProps {
  data: AnalysisState;
}

const ExportView: React.FC<ExportViewProps> = ({ data }) => {
  const { t } = useTranslation();

  // --- Global Settings ---
  const allPeriods = useMemo(() => 
    data.students[0]?.history.map(h => h.period) || [], 
    [data.students]
  );
  const [selectedPeriod, setSelectedPeriod] = useState<string>(allPeriods[allPeriods.length - 1] || '');
  const [exportTab, setExportTab] = useState<ExportTab>('overall');

  // --- OVERALL REPORT STATES ---
  const [sections, setSections] = useState({
    overview: true,
    school: true,
    comparison: false,
    kings: false,
    parameters: false,
    subject: false
  });
  const [compClasses, setCompClasses] = useState<string[]>(data.classes);
  const [benchmarkClass, setBenchmarkClass] = useState<string>(data.classes[0] || '');
  const [exportSubjects, setExportSubjects] = useState<string[]>([data.subjects[0] || '']);
  const [subjectClasses, setSubjectClasses] = useState<string[]>(data.classes);

  // --- PERSONAL REPORT STATES ---
  const [indivClass, setIndivClass] = useState<string>(data.classes[0] || '');
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);
  const [studentSearch, setStudentSearch] = useState('');

  // --- TABLE REPORT STATES ---
  const [tableOptions, setTableOptions] = useState({
    rawScore: true,
    ranks: true,
    stats: true
  });

  // --- Logic Hook ---
  const {
    allHistoricalRanks,
    allSubjectRanks,
    allClassHistoricalRanks,
    periodData,
    overviewStats,
    schoolStats,
    comparisonData,
    kingsData,
    duelData,
    classFirstStudentName,
    schoolFirstStudentName,
    paramsData,
    subjectAnalysisData,
    getStatusLabel,
    getSubjectCellStyle
  } = useExportData({
    data,
    selectedPeriod,
    compClasses,
    benchmarkClass,
    exportSubjects,
    subjectClasses
  });

  // Reset students when class changes
  useEffect(() => {
    setSelectedStudentIds([]);
  }, [indivClass]);

  const toggleSection = (key: keyof typeof sections) => setSections(prev => ({ ...prev, [key]: !prev[key] }));
  const handlePrint = () => window.print();

  return (
    <div className="flex flex-col lg:flex-row gap-8 animate-in fade-in duration-500 print:block">
      <ExportSidebar 
        data={data}
        allPeriods={allPeriods}
        selectedPeriod={selectedPeriod}
        setSelectedPeriod={setSelectedPeriod}
        exportTab={exportTab}
        setExportTab={setExportTab}
        sections={sections}
        toggleSection={toggleSection}
        compClasses={compClasses}
        setCompClasses={setCompClasses}
        benchmarkClass={benchmarkClass}
        setBenchmarkClass={setBenchmarkClass}
        exportSubjects={exportSubjects}
        setExportSubjects={setExportSubjects}
        subjectClasses={subjectClasses}
        setSubjectClasses={setSubjectClasses}
        indivClass={indivClass}
        setIndivClass={setIndivClass}
        selectedStudentIds={selectedStudentIds}
        setSelectedStudentIds={setSelectedStudentIds}
        studentSearch={studentSearch}
        setStudentSearch={setStudentSearch}
        tableOptions={tableOptions}
        setTableOptions={setTableOptions}
        handlePrint={handlePrint}
      />

      <ReportShell
        title={exportTab === 'overall' ? t('export.tab_overall') : exportTab === 'personal' ? t('export.tab_personal') : t('export.tab_tables')}
        subtitle={selectedPeriod}
      >
        {exportTab === 'overall' && (
          <OverallReport 
            sections={sections}
            overviewStats={overviewStats}
            schoolStats={schoolStats}
            comparisonData={comparisonData}
            kingsData={kingsData}
            duelData={duelData}
            classFirstStudentName={classFirstStudentName}
            schoolFirstStudentName={schoolFirstStudentName}
            benchmarkClass={benchmarkClass}
            paramsData={paramsData}
            subjectAnalysisData={subjectAnalysisData}
            compClasses={compClasses}
            totalClasses={data.classes.length}
          />
        )}

        {exportTab === 'personal' && (
          selectedStudentIds.length > 0 ? (
            <PersonalReport 
              students={data.students}
              selectedStudentIds={selectedStudentIds}
              selectedPeriod={selectedPeriod}
              allHistoricalRanks={allHistoricalRanks}
              allClassHistoricalRanks={allClassHistoricalRanks}
              allSubjectRanks={allSubjectRanks}
              periodData={periodData}
              subjects={data.subjects}
              totalStudents={data.students.length}
              getStatusLabel={getStatusLabel}
              getSubjectCellStyle={getSubjectCellStyle}
            />
          ) : (
            <div className="p-10 text-center text-gray-400 italic border-2 border-dashed rounded-xl">
              Please select students from the sidebar to generate reports.
            </div>
          )
        )}

        {exportTab === 'tables' && (
          <TableReport 
            tableOptions={tableOptions}
            periodData={periodData}
            subjects={data.subjects}
            selectedPeriod={selectedPeriod}
            allSubjectRanks={allSubjectRanks}
          />
        )}
      </ReportShell>
    </div>
  );
};

export default ExportView;

import React from 'react';
import { 
  GraduationCap, Target, Zap, ShieldAlert, Flame, TrendingUp, TrendingDown, Table as TableIcon
} from 'lucide-react';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, 
  ResponsiveContainer, RadarChart, PolarGrid, 
  PolarAngleAxis, PolarRadiusAxis, Radar 
} from 'recharts';
import { StudentRecord } from '../../types';
import * as AnalysisEngine from '../../utils/analysisUtils';
import { useTranslation } from '../../context/LanguageContext';

interface PersonalReportProps {
  students: StudentRecord[];
  selectedStudentIds: string[];
  selectedPeriod: string;
  allHistoricalRanks: Record<string, Record<string, number>>;
  allClassHistoricalRanks: Record<string, Record<string, number>>;
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>;
  periodData: any[];
  subjects: string[];
  totalStudents: number;
  getStatusLabel: (period: string, studentName: string, student: StudentRecord) => string;
  getSubjectCellStyle: (period: string, subject: string, studentName: string) => string;
}

const PersonalReport: React.FC<PersonalReportProps> = ({
  students,
  selectedStudentIds,
  selectedPeriod,
  allHistoricalRanks,
  allClassHistoricalRanks,
  allSubjectRanks,
  periodData,
  subjects,
  totalStudents,
  getStatusLabel,
  getSubjectCellStyle
}) => {
  const { t, language } = useTranslation();

  return (
    <div className="space-y-0">
      {selectedStudentIds.map((studentId) => {
        const student = students.find(s => s.id === studentId);
        if (!student) return null;

        const swot = AnalysisEngine.getStudentSWOT(student, selectedPeriod, subjects, allHistoricalRanks, allSubjectRanks, totalStudents);
        const radar = AnalysisEngine.getStudentRadarData(student, selectedPeriod, subjects, 'grade', periodData);
        const history = student.history.map(h => ({
          period: h.period,
          totalScore: h.totalScore,
          schoolRank: allHistoricalRanks[h.period]?.[student.name]
        }));
        const streak = AnalysisEngine.calculateStreakInfo(student, allHistoricalRanks);
        const historyMeanTotal = student.history.reduce((acc, h) => acc + h.totalScore, 0) / student.history.length;

        const firstTotal = student.history[0].totalScore;
        const lastTotal = student.history[student.history.length - 1].totalScore;
        const improvement = student.history.length > 1 ? ((lastTotal - firstTotal) / firstTotal) * 100 : 0;
        const improvementStr = student.history.length > 1 ? (improvement > 0 ? `+${improvement.toFixed(1)}%` : `${improvement.toFixed(1)}%`) : 'N/A';

        return (
          <div key={studentId} className="print:break-after-page print:min-h-screen print:flex print:flex-col pb-10 border-b-8 border-gray-100 mb-10 print:border-none print:mb-0 print:pb-0">
            {/* Header - Outline Style for Print Savings */}
            <div className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm w-full mb-6">
              <div className="flex justify-between items-start">
                <div>
                  <div className="flex items-center gap-3 mb-2">
