    periodData,
    overviewStats,
    schoolStats,
    comparisonData,
    kingsData,
    duelData,
    classFirstStudentName,
    schoolFirstStudentName,
    paramsData,
    subjectAnalysisData,
    getStatusLabel,
    getSubjectCellStyle
  } = useExportData({
    data,
    selectedPeriod,
    compClasses,
    benchmarkClass,
    exportSubjects,
    subjectClasses
  });

  // Reset students when class changes
  useEffect(() => {
    setSelectedStudentIds([]);
  }, [indivClass]);

  const toggleSection = (key: keyof typeof sections) => setSections(prev => ({ ...prev, [key]: !prev[key] }));
